import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, Building2, Calendar, Check, CheckCircle2, ChevronDown, ChevronRight, ClipboardList, Clock3, Download, FileText, FolderOpen, HelpCircle, Image as ImageIcon, Layers3, LayoutDashboard, Link2, Loader2, LockKeyhole, LogOut, Menu, MoreHorizontal, Paperclip, Pencil, Play, Plus, Search, Settings2, ShieldCheck, Sparkles, Target, Trash2, Upload, Users, Video, X } from 'lucide-react';
