const ProcessMap = dynamic(() => import('./operations/ProcessMap'), { loading: loadingWorkspace });
const Delivery = dynamic(() => import('./operations/Delivery'), { loading: loadingWorkspace });
const AutomationCenter = dynamic(() => import('./operations/AutomationCenter'), { loading: loadingWorkspace });
const BenefitAnalysis = dynamic(() => import('./operations/BenefitAnalysis'), { loading: loadingWorkspace });
const StoreLibrary = dynamic(() => import('./operations/StoreLibrary'), { loading: loadingWorkspace });
const JobWorkspace = dynamic(() => import('./jobs/JobWorkspace'), { loading: loadingWorkspace });
const SessionPreparation = dynamic(() => import('./jobs/JobTaskList'), { loading: loadingWorkspace });
