type View = 'overview' | 'departments' | 'sessions' | 'opportunities' | 'roadmap' | 'results' | 'reports' | 'settings' | 'map' | 'automations' | 'library' | 'jobs';
type ModalState = { kind: 'process'; record: Process; tab?: string } | { kind: 'session'; record: Session } | { kind: 'measurement'; record: Measurement } | null;
type App = ReturnType<typeof useAtlas>;
const NAV = [
  { id: 'overview', label: 'Visión general', icon: LayoutDashboard },
  { id: 'departments', label: 'Departamentos', icon: Building2 },
  { id: 'jobs', label: 'Puestos y tareas', icon: Users },
  { id: 'map', label: 'Mapa de procesos', icon: Link2 },
  { id: 'sessions', label: 'Sesiones de trabajo', icon: Calendar },
  { id: 'opportunities', label: 'Oportunidades', icon: Sparkles },
  { id: 'roadmap', label: 'Implantaciones', icon: Layers3 },
  { id: 'automations', label: 'Automatizaciones', icon: Activity },
  { id: 'results', label: 'Resultados y ROI', icon: BarChart3 },
  { id: 'library', label: 'Biblioteca de mejoras', icon: FolderOpen },
  { id: 'reports', label: 'Informes', icon: FileText },
] as const;
const COMPANY_NAMES: Record<string, string> = { JTQ: 'Joyería Te Quiero', TQM: 'Te Quiero Metales', Ambas: 'Ambas empresas' };
const DEPT_ICONS: Record<string, string> = { contabilidad: 'CO', finanzas: 'FI', compras: 'CP', ventas: 'VE', rrhh: 'PE', marketing: 'MK', it: 'IT', direccion: 'DI', logistica: 'LO', tiendas: 'TI' };
const PROMPTS: Record<string, string[]> = {
  contabilidad: ['¿Qué documentos se reciben, se revisan y se vuelven a introducir?', '¿Qué conciliaciones y comprobaciones consumen más tiempo?', '¿Qué cambia con el paso de A3CON a Sage 200?', '¿Dónde aparecen errores y cuánto trabajo cuesta corregirlos?'],
  finanzas: ['¿Cómo se prepara la previsión de tesorería?', '¿Qué datos se reúnen para cierres e informes?', '¿Qué aprobaciones necesitan los pagos y sus excepciones?', '¿Qué información se solicita repetidamente a otras áreas?'],
  compras: ['¿Cómo se detecta una necesidad y se prepara un pedido?', '¿Cómo se comparan precios, plazos y condiciones?', '¿Qué trabajo exige confirmar y seguir los pedidos?', '¿Qué sucede cuando el proveedor entrega una excepción?'],
  ventas: ['¿Qué trabajo administrativo acompaña a cada venta?', '¿Qué consultas y seguimientos se repiten?', '¿Qué información se duplica entre canales y sistemas?', '¿Cómo se resuelven cambios y otras excepciones?'],
  rrhh: ['¿Qué documentación exige cada alta, cambio y baja?', '¿Qué pasos se repiten entre Factorial y otros sistemas?', '¿Qué consultas de los equipos se repiten?', '¿Qué tareas podrían automatizarse sin evaluar a las personas?'],
  marketing: ['¿Cómo se prepara y aprueba una campaña?', '¿Qué contenidos y datos se adaptan a cada canal?', '¿Qué informes se componen manualmente?', '¿Qué verificaciones exige cada publicación?'],
  it: ['¿Qué incidencias y solicitudes se repiten?', '¿Qué exportaciones y cruces de datos se hacen a mano?', '¿Qué dependencias tiene el ERP a medida?', '¿Cómo se comprueba y documenta que un cambio funciona?'],
  direccion: ['¿Qué información se necesita para decidir cada semana?', '¿Qué informes llegan tarde o exigen conciliación?', '¿Qué aprobaciones podrían seguir reglas conocidas?', '¿Qué evidencia exige Dirección para aprobar una mejora?'],
  logistica: ['¿Cómo se preparan, documentan y siguen los envíos?', '¿Qué información se introduce más de una vez?', '¿Dónde se pierde la trazabilidad entre operaciones?', '¿Cómo se gestionan diferencias, devoluciones y excepciones?'],
  tiendas: ['¿Qué tareas se repiten al abrir, operar y cerrar?', '¿Qué consultas o peticiones se envían a oficina?', '¿Qué pasos comunes consumen más tiempo en las 18 tiendas?', '¿Qué casos reales permitirían verificar el proceso estándar?'],
};
const number = (n: number | null | undefined, digits = 1) => n === null || n === undefined || !Number.isFinite(n) ? '—' : new Intl.NumberFormat('es-ES', { maximumFractionDigits: digits }).format(n);
const money = (n: number | null | undefined) => n === null || n === undefined || !Number.isFinite(n) ? '—' : new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(n);
const date = (d: string | undefined) => d ? new Date(d.length === 10 ? d + 'T12:00:00' : d).toLocaleDateString('es-ES', { day: 'numeric', month: 'short', year: 'numeric' }) : 'Sin fecha';
const monthName = (d: string) => new Date(d + '-15T12:00:00').toLocaleDateString('es-ES', { month: 'short', year: 'numeric' });
const deptName = (id: string) => DEPARTMENTS.find(d => d.id === id)?.name ?? id;
const makeId = () => crypto.randomUUID();
const now = () => new Date().toISOString();
const localDate = () => new Intl.DateTimeFormat('en-CA', { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: 'Atlantic/Canary' }).format(new Date());
const filesize = (n = 0) => n > 1048576 ? `${number(n / 1048576)} MB` : `${number(n / 1024, 0)} KB`;

function Brand({ compact = false }: { compact?: boolean }) {
  return <div className={`brand ${compact ? 'brand-compact' : ''}`}><span className="brand-symbol" aria-hidden="true"><i /><i /><i /></span><div><strong>ATLAS</strong></div></div>;
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: string }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Status({ status }: { status: ProcessStatus }) { return <Badge tone={status === 'implemented' ? 'green' : status === 'pilot' ? 'blue' : status === 'approved' ? 'violet' : status === 'paused' ? 'amber' : 'neutral'}>{STATUS_LABELS[status]}</Badge>; }
function EvidenceBadge({ level }: { level: string }) { return <Badge tone={level === 'validated' ? 'green' : level === 'observed' ? 'blue' : 'neutral'}>{level === 'validated' ? 'Validado' : level === 'observed' ? 'Observado' : 'Estimación'}</Badge>; }
function Empty({ icon: Icon = FolderOpen, title, text, action }: { icon?: any; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon"><Icon size={25} strokeWidth={1.5} /></span><h3>{title}</h3><p>{text}</p>{action}</div>; }
function Button({ children, onClick, variant = 'primary', disabled, className = '', type = 'button' }: { children: ReactNode; onClick?: () => void; variant?: string; disabled?: boolean; className?: string; type?: 'button' | 'submit' }) { return <button type={type} className={`btn btn-${variant} ${className}`} onClick={onClick} disabled={disabled}>{children}</button>; }
function Field({ label, hint, children, className = '' }: { label: string; hint?: string; children: ReactNode; className?: string }) { return <label className={`field ${className}`}><span className="field-label">{label}</span>{children}{hint && <span className="field-hint">{hint}</span>}</label>; }
function NumberField({ label, value, onChange, hint, suffix, max, min = 0, disabled = false, step = 'any' }: { label: string; value: number; onChange: (n: number) => void; hint?: string; suffix?: string; max?: number; min?: number; disabled?: boolean; step?: string }) { return <Field label={label} hint={hint}><div className="input-with-unit"><input type="number" inputMode="decimal" min={min} max={max} step={step} value={Number.isFinite(value) ? value : ''} onChange={e => onChange(e.target.value === '' ? 0 : Number(e.target.value))} disabled={disabled} />{suffix && <span>{suffix}</span>}</div></Field>; }
function Score({ score, small = false }: { score: number; small?: boolean }) { return <span className={`score ${small ? 'score-small' : ''} ${score >= 60 ? 'score-high' : score >= 35 ? 'score-mid' : ''}`}>{number(score, 0)}</span>; }
function SectionHead({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="section-head"><div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{description && <p className="section-description">{description}</p>}</div>{action && <div className="section-action">{action}</div>}</div>; }
function Metric({ label, value, unit, detail, accent = false, icon: Icon }: { label: string; value: ReactNode; unit?: string; detail: string; accent?: boolean; icon?: any }) { return <div className={`metric-card ${accent ? 'metric-accent' : ''}`}><div className="metric-top"><span>{label}</span>{Icon && <Icon size={17} />}</div><div className="metric-value">{value}{unit && <small>{unit}</small>}</div><p>{detail}</p></div>; }
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const container = useRef<HTMLDivElement>(null); const onCloseRef = useRef(onClose); onCloseRef.current = onClose;
  useEffect(() => { const old = document.body.style.overflow; document.body.style.overflow = 'hidden'; const previous = document.activeElement as HTMLElement; const focus = () => { if (!container.current?.contains(document.activeElement)) container.current?.querySelector<HTMLElement>('button,input,select,textarea')?.focus(); }; const frame = requestAnimationFrame(focus); const key = (e: KeyboardEvent) => { if ([...document.querySelectorAll('[role="dialog"]')].at(-1) !== container.current) return; if (e.key === 'Escape') onCloseRef.current(); if (e.key === 'Tab') { const list = container.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]'); if (!list?.length) return; const first = list[0], last = list[list.length - 1]; if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); } } }; window.addEventListener('keydown', key); return () => { cancelAnimationFrame(frame); document.body.style.overflow = old; window.removeEventListener('keydown', key); previous?.focus?.(); }; }, []);
  return <div className="modal-scrim" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true" aria-label={title} ref={container}><header className="modal-head"><div><p className="eyebrow">ATLAS / ESPACIO DE TRABAJO</p><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-btn" onClick={onClose} aria-label="Cerrar"><X size={21} /></button></header>{children}</div></div>;
}

export default function AtlasApp() {
  const app: any = useAtlas();
  const state: AtlasState = app.state;
  const [view, setView] = useState<View>('overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [company, setCompany] = useState('all');
  const [query, setQuery] = useState('');
  const [department, setDepartment] = useState('all');
  const [status, setStatus] = useState('all');
  const [selectedDept, setSelectedDept] = useState<DepartmentId | null>(null);
  const [modal, setModal] = useState<ModalState>(null);
  const [toast, setToast] = useState<{ text: string; error?: boolean } | null>(null);
  const [busy, setBusy] = useState('');
  const [reportDepartment, setReportDepartment] = useState('all');
  const importInput = useRef<HTMLInputElement>(null);
  const canWrite = app.user?.role !== 'director';
  const isCloud = app.mode === 'cloud' || app.mode === 'supabase';
  const isDemo = app.mode === 'demo';
  const notify = (text: string, error = false) => setToast({ text, error });
  const run = async (action: () => Promise<any> | any, success?: string, name = 'action') => { setBusy(name); try { await action(); if (success) notify(success); } catch (e: any) { notify(e?.message || 'No se ha podido completar la acción.', true); } finally { setBusy(''); } };
  useEffect(() => { if (!toast) return; const t = window.setTimeout(() => setToast(null), toast.error ? 9000 : 4500); return () => clearTimeout(t); }, [toast]);
  const navigate = (next: View) => { setView(next); setMobileNav(false); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const allProcesses = useMemo(() => (state?.processes || []).filter(p => company === 'all' || p.company === company || p.company === 'Ambas'), [state?.processes, company]);
  const allSessions = useMemo(() => (state?.sessions || []).filter(s => company === 'all' || s.company === company || s.company === 'Ambas'), [state?.sessions, company]);
  const allMeasurements = useMemo(() => (state?.measurements || []).filter(m => allProcesses.some(p => p.id === m.processId)), [state?.measurements, allProcesses]);
  const stats = useMemo(() => state ? aggregateMetrics(allProcesses, state.settings, allMeasurements) : null, [allProcesses, allMeasurements, state]);
  const processes = useMemo(() => allProcesses.filter(p => (department === 'all' || p.departmentId === department) && (status === 'all' || p.status === status) && (!query || `${p.name} ${p.description} ${p.owner} ${deptName(p.departmentId)}`.toLowerCase().includes(query.toLowerCase()))).sort((a, b) => priorityScore(b, state.settings) - priorityScore(a, state.settings)), [allProcesses, department, status, query, state]);
  const visitedDepts = new Set(allSessions.filter(s => s.status === 'completed').map(s => s.departmentId));
  const verified = allMeasurements.map(m => { const p = allProcesses.find(p => p.id === m.processId)!; return { m, p, comparison: compareMeasurement(p, m) }; }).filter(x => x.comparison.kind === 'verified');
  const latestMonth = [...new Set(verified.map(x => x.m.month))].sort().at(-1);
  const latestVerified = verified.filter(x => x.m.month === latestMonth);
  const actualStats = state ? aggregateMeasuredResults(allProcesses, allMeasurements) : null;
  const newProcess = (dept?: DepartmentId) => setModal({ kind: 'process', record: createProcess({ departmentId: dept || (department !== 'all' ? department as DepartmentId : 'contabilidad'), company: company !== 'all' ? company as any : 'JTQ' }) });
  const newSession = (dept?: DepartmentId, selectedDate?: string) => setModal({ kind: 'session', record: { id: makeId(), company: company !== 'all' ? company as any : 'JTQ', departmentId: dept || selectedDept || 'contabilidad', title: '', date: selectedDate || localDate(), owner: 'Miguel Ángel', participants: [], notes: '', status: 'planned', processIds: [], createdAt: now(), updatedAt: now() } });
  const newMeasurement = (process?: Process) => { if (!allProcesses.length) { notify('Registra primero una oportunidad para asociar la medición.', true); return; } const p = process || allProcesses.find(p => p.baseline) || allProcesses[0]; setModal({ kind: 'measurement', record: { id: makeId(), processId: p.id, month: localDate().slice(0, 7), volume: 0, minutesPerCase: 0, peoplePerCase: 1, errors: 0, minutesPerError: 0, reviewMinutes: 0, runningCost: 0, realCashSaved: 0, source: '', validated: false, notes: '', createdAt: now(), updatedAt: now() } }); };
  const changeStatus = (p: Process, next: ProcessStatus) => { if (next === 'pilot' && !p.baseline) { notify('Fija la línea base del proceso antes de comenzar el piloto.', true); setModal({ kind: 'process', record: p, tab: 'measurement' }); return; } if (next === 'pilot' && state.processes.some(other => other.id !== p.id && other.status === 'pilot') && !window.confirm('Ya existe otro piloto activo. La planificación recomienda uno simultáneo. ¿Quieres iniciar también este?')) return; run(() => app.saveProcess({ ...p, status: next, updatedAt: now() }), 'Estado actualizado.'); };
  const renderProcessTable = (list: Process[], compact = false) => list.length ? <div className="table-scroll"><table className="process-table"><thead><tr><th>Prioridad</th><th>Oportunidad</th>{!compact && <th>Tiempo potencial</th>}<th>Estado</th>{!compact && <th>Evidencia</th>}<th><span className="sr-only">Abrir</span></th></tr></thead><tbody>{list.map(p => { const m = calculateMetrics(p); return <tr key={p.id} onClick={() => setModal({ kind: 'process', record: p })} tabIndex={0} onKeyDown={e => { if (e.key === 'Enter') setModal({ kind: 'process', record: p }); }}><td><Score small score={priorityScore(p, state.settings)} /></td><td><strong>{p.name || 'Proceso sin nombre'}</strong><span className="table-subtitle">{deptName(p.departmentId)} <i /> {p.company}</span></td>{!compact && <td className="tabular">{number(m.netHoursFreedMonthly)} <span className="muted">h/mes</span></td>}<td><Status status={p.status} /></td>{!compact && <td><EvidenceBadge level={p.evidenceLevel} /></td>}<td><ArrowUpRight size={17} className="muted" /></td></tr>; })}</tbody></table></div> : <Empty icon={Sparkles} title={query || department !== 'all' || status !== 'all' ? 'No hay coincidencias' : 'La primera oportunidad está por descubrir'} text={query || department !== 'all' || status !== 'all' ? 'Prueba a cambiar los filtros de búsqueda.' : 'Registra una tarea real, sus tiempos y sus dificultades. ATLAS te ayudará a compararla con las demás.'} action={canWrite && <Button onClick={() => newProcess()}><Plus size={17} />Registrar oportunidad</Button>} />;

  const operationsProps = { state, processes: allProcesses, canWrite, actor: app.user?.email || 'Responsable del programa', saveProcess: app.saveProcess, openProcess: (p: Process) => setModal({ kind: 'process', record: p }), notify };

  if (!app.ready || !state || !stats) return <div className="app-loading"><Brand /><div className="loading-orbit" /><p>Preparando tu espacio de trabajo</p></div>;

  return <div className={`app-shell ${sidebarCollapsed ? 'sidebar-collapsed' : ''}`}>
    <a className="skip-link" href="#main-content">Ir al contenido</a>
    {mobileNav && <button className="nav-scrim" onClick={() => setMobileNav(false)} aria-label="Cerrar navegación" />}
    <aside className={`sidebar ${mobileNav ? 'is-open' : ''}`}><div className="sidebar-brand"><Brand /><button className="icon-btn mobile-only" onClick={() => setMobileNav(false)} aria-label="Cerrar menú"><X size={20} /></button></div><p className="nav-label">Espacio de trabajo</p><nav aria-label="Navegación principal">{NAV.map(item => <button className={`nav-item ${view === item.id ? 'active' : ''}`} key={item.id} aria-current={view === item.id ? 'page' : undefined} onClick={() => navigate(item.id)}><span className={`nav-icon nav-icon-${item.id}`}><item.icon size={16} strokeWidth={1.8} /></span><span>{item.label}</span>{item.id === 'opportunities' && state.processes.length > 0 && <small>{state.processes.length}</small>}</button>)}</nav><button className="sidebar-today" onClick={() => navigate('sessions')}><span className="sidebar-date-icon"><span>{new Date(localDate() + 'T12:00:00').toLocaleDateString('es-ES', { month: 'short' })}</span><strong>{Number(localDate().slice(-2))}</strong></span><span><strong>Tu agenda</strong><small>{allSessions.filter(s => s.date === localDate()).length} sesiones hoy</small></span><ChevronRight size={15} /></button><div className="sidebar-bottom"><div className={`storage-card ${isCloud ? 'storage-cloud' : ''}`}><span className="status-dot" /><div><strong>{isDemo ? 'Espacio de ejemplo' : isCloud ? 'Espacio conectado' : 'Guardado en este navegador'}</strong><p>{isDemo ? 'Datos ficticios separados' : isCloud ? 'Datos compartidos con tu equipo' : 'Exporta una copia al terminar'}</p></div></div><button className={`nav-item ${view === 'settings' ? 'active' : ''}`} onClick={() => navigate('settings')}><span className="nav-icon nav-icon-settings"><Settings2 size={16} /></span><span>Configuración</span></button><div className="profile"><span className="avatar">{app.user?.role === 'director' ? 'DI' : 'MA'}</span><div><strong>{app.user?.role === 'director' ? 'Dirección' : 'Miguel Ángel'}</strong><span>{app.user?.role === 'director' ? 'Consulta del programa' : 'Responsable del programa'}</span></div><ShieldCheck size={17} /></div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="topbar-left"><button className="icon-btn sidebar-toggle" aria-label={sidebarCollapsed ? 'Mostrar barra lateral' : 'Ocultar barra lateral'} aria-expanded={!sidebarCollapsed} onClick={() => setSidebarCollapsed(!sidebarCollapsed)}><Menu size={19} /></button><button className="icon-btn mobile-only" onClick={() => setMobileNav(true)} aria-label="Abrir menú"><Menu size={22} /></button><span>{view === 'settings' ? 'Configuración' : NAV.find(n => n.id === view)?.label}</span></div><div className="topbar-right"><ThemePicker /><div className="search-box"><Search size={16} /><input aria-label="Buscar oportunidades" placeholder="Buscar oportunidades" value={query} onChange={e => { setQuery(e.target.value); if (e.target.value) navigate('opportunities'); }} /></div><span className={`save-indicator ${/error|no se ha guardado|no se pudo|bloquead/i.test(String(app.syncStatus)) ? 'save-error' : ''}`}><span className="status-dot" />{/guardando/i.test(String(app.syncStatus)) ? 'Guardando' : /error|no se ha guardado|no se pudo|bloquead/i.test(String(app.syncStatus)) ? 'Revisar guardado' : isCloud ? 'Conectado' : 'Local'}</span></div></header>
    <main className={`main-content ${view === 'sessions' ? 'agenda-content' : ''}`} id="main-content">
      <div className="scope-row"><span><span className="scope-dot" /> Tu espacio de mejora</span><label className="scope-select"><Building2 size={14} /><select aria-label="Filtrar por empresa" value={company} onChange={e => setCompany(e.target.value)}><option value="all">Todas las empresas</option><option value="JTQ">Joyería Te Quiero</option><option value="TQM">Te Quiero Metales</option></select><ChevronDown size={13} /></label></div>
      {isDemo && <div className="notice notice-demo"><Sparkles size={17} /><span>Estás explorando datos ficticios. Tus datos reales permanecen separados.</span><button onClick={() => run(() => app.clearDemo(), 'Has vuelto a tu espacio real.')}>Volver a mis datos <ArrowRight size={14} /></button></div>}
      {!isDemo && !isCloud && <div className="local-note"><span><LockKeyhole size={13} />Modo local · Los datos y adjuntos permanecen en este navegador.</span><button onClick={() => run(() => app.exportBackup(), 'Copia completa descargada.', 'backup')}><Download size={13} />Exportar copia</button></div>}

      {view === 'overview' && <div className="view-enter"><section className="overview-hero">
        <div className="hero-copy"><p className="hero-label">{new Date(localDate() + 'T12:00:00').toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</p><h1>Visión general</h1><p>Las conversaciones de hoy. Las mejoras de mañana.</p><div className="hero-actions">{canWrite && <Button onClick={() => newSession()}><Plus size={16} />Nueva sesión</Button>}<button className="text-button" onClick={() => navigate('departments')}>Explorar departamentos <ArrowRight size={15} /></button></div></div>
        <button className="overview-calendar-link" onClick={() => navigate('sessions')}><span className="overview-calendar-date"><small>{new Date(localDate() + 'T12:00:00').toLocaleDateString('es-ES', { month: 'long' })}</small><strong>{Number(localDate().slice(-2))}</strong><span>{new Date(localDate() + 'T12:00:00').toLocaleDateString('es-ES', { weekday: 'long' })}</span></span><span className="overview-calendar-caption">Abrir calendario <ArrowUpRight size={13} /></span></button>
      </section>
      <div className="metrics-grid"><Metric label="Tiempo potencial" value={stats.processCount ? number(stats.netHoursFreedMonthly) : '—'} unit={stats.processCount ? 'h/mes' : ''} detail="Estimación neta de supervisión" icon={Clock3} accent /><Metric label="Ahorro de caja previsto" value={stats.processCount ? money(stats.netCashBenefitMonthly) : '—'} detail="Mensual, tras costes recurrentes" icon={Activity} /><Metric label="Oportunidades" value={allProcesses.length} detail={`${stats.implementedCount} implantadas en el ámbito actual`} icon={Sparkles} /><Metric label="Áreas entrevistadas" value={visitedDepts.size} unit="/ 10" detail="Sesiones marcadas como completadas" icon={Building2} /></div>
      <div className="overview-two"><section className="panel start-panel"><div className="panel-title"><div><p className="eyebrow">PRÓXIMO PASO</p><h2>{allSessions.length ? 'Las conversaciones en marcha' : 'Escuchar antes de automatizar'}</h2></div><span className="round-icon"><ClipboardList size={20} /></span></div>{allSessions.length ? <div className="session-mini-list">{[...allSessions].sort((a,b) => a.date.localeCompare(b.date)).slice(0,3).map(s => <button key={s.id} onClick={() => setModal({ kind: 'session', record: s })}><div className="date-square"><strong>{new Date(s.date + 'T12:00:00').getDate()}</strong><span>{new Date(s.date + 'T12:00:00').toLocaleDateString('es-ES',{month:'short'})}</span></div><div><strong>{s.title}</strong><span>{deptName(s.departmentId)} · {s.company}</span></div><ChevronRight size={17} /></button>)}</div> : <><p className="panel-copy">Elige un departamento y reserva una conversación. Reúne las notas y las evidencias en un mismo lugar.</p><div className="first-session"><div className="date-square"><strong>{Number(localDate().slice(-2))}</strong><span>{new Date(localDate() + 'T12:00:00').toLocaleDateString('es-ES', { month: 'short' })}</span></div><div><strong>Primera entrevista de diagnóstico</strong><span>Responsable y personas que ejecutan el trabajo</span></div><span className="quiet-pill">Por programar</span></div></> }<button className="panel-link" onClick={() => navigate('sessions')}>Abrir sesiones de trabajo <ArrowRight size={15} /></button></section><section className="panel progress-panel"><div className="panel-title"><div><p className="eyebrow">COBERTURA DEL PROGRAMA</p><h2>Una visión de toda la empresa</h2></div></div><div className="coverage-numbers"><div><strong>02</strong><span>empresas</span></div><div><strong>10</strong><span>departamentos</span></div><div><strong>18</strong><span>tiendas</span></div></div><div className="coverage-track">{DEPARTMENTS.map(d => <span key={d.id} className={visitedDepts.has(d.id) ? 'covered' : ''} title={d.name} />)}</div><p className="coverage-caption">{visitedDepts.size === 0 ? 'El diagnóstico empieza con la primera conversación.' : `${visitedDepts.size} de 10 áreas con al menos una entrevista completada.`}</p><div className="coverage-foot"><span><span className="legend-dot blue" />Entrevistadas</span><span><span className="legend-dot" />Pendientes</span><button onClick={() => navigate('departments')}>Ver áreas <ArrowUpRight size={14} /></button></div></section></div>
      <section className="panel opportunities-panel"><div className="panel-title"><div><p className="eyebrow">CARTERA DE MEJORAS</p><h2>Oportunidades con mayor prioridad</h2></div><button className="text-button" onClick={() => navigate('opportunities')}>Ver todas <ArrowRight size={15} /></button></div>{renderProcessTable([...allProcesses].sort((a,b)=>priorityScore(b,state.settings)-priorityScore(a,state.settings)).slice(0,4), true)}</section>
      <div className="method-strip"><span className="method-icon"><Target size={21} /></span><div><strong>El resultado se comprueba cada mes.</strong><p>Horas liberadas, ahorro económico y errores se registran por separado, con su fuente y su validación.</p></div><button className="text-button" onClick={() => navigate('results')}>Cómo mediremos <ArrowUpRight size={15} /></button></div></div>}

      {view === 'departments' && <div className="view-enter"><SectionHead eyebrow="01 / DESCUBRIMIENTO" title={selectedDept ? deptName(selectedDept) : 'El trabajo, área por área.'} description={selectedDept ? 'Documenta el trabajo real, sus puntos de fricción y las oportunidades de mejora.' : 'Diez perspectivas para construir un diagnóstico compartido.'} action={selectedDept ? <Button variant="secondary" onClick={() => setSelectedDept(null)}><ArrowLeft size={16} />Todos los departamentos</Button> : <Badge>{visitedDepts.size} de 10 entrevistados</Badge>} />{selectedDept ? <><div className="department-detail-grid"><section className="panel interview-guide"><p className="eyebrow">GUÍA PARA LA CONVERSACIÓN</p><h2>Preguntas que abren el proceso</h2><ol>{PROMPTS[selectedDept].map((q,i) => <li key={q}><span>{String(i+1).padStart(2,'0')}</span><p>{q}</p></li>)}</ol><div className="button-row">{canWrite && <Button onClick={() => newSession(selectedDept)}><Plus size={16} />Nueva sesión</Button>}</div></section><section className="panel dept-summary"><span className="dept-monogram large">{DEPT_ICONS[selectedDept]}</span><h2>{deptName(selectedDept)}</h2><p>{selectedDept === 'tiendas' ? '18 tiendas · 70 personas. Entrevista con la encargada y verificación de ejemplos de los procesos comunes.' : selectedDept === 'ventas' ? '6 personas en el departamento de Ventas.' : ['contabilidad','finanzas'].includes(selectedDept) ? 'Contabilidad y Finanzas suman 6 personas. El reparto por área se confirmará en las entrevistas.' : 'La dimensión y las tareas del equipo se documentarán durante el diagnóstico.'}</p><div className="detail-facts"><div><span>Sesiones</span><strong>{allSessions.filter(s=>s.departmentId===selectedDept).length}</strong></div><div><span>Oportunidades</span><strong>{allProcesses.filter(p=>p.departmentId===selectedDept).length}</strong></div><div><span>Evidencias</span><strong>{state.evidence.filter((e:any)=>e.departmentId===selectedDept||allProcesses.some(p=>p.id===e.processId&&p.departmentId===selectedDept)).length}</strong></div></div></section></div><section className="panel"><div className="panel-title"><h2>Oportunidades del departamento</h2>{canWrite && <Button variant="secondary" onClick={() => newProcess(selectedDept)}><Plus size={15} />Registrar</Button>}</div>{renderProcessTable(allProcesses.filter(p=>p.departmentId===selectedDept))}</section></> : <><div className="department-grid">{DEPARTMENTS.map((d,i) => { const ps=allProcesses.filter(p=>p.departmentId===d.id); const ss=allSessions.filter(s=>s.departmentId===d.id); return <button key={d.id} className="department-card" onClick={() => setSelectedDept(d.id)} style={{'--card-delay':`${i*30}ms`} as any}><div className="department-card-top"><span className={`dept-monogram dept-tone-${i%4}`}>{DEPT_ICONS[d.id]}</span><ArrowUpRight size={18} /></div><h3>{d.name}</h3><p>{d.id==='tiendas'?'18 tiendas · 70 personas':d.id==='ventas'?'6 personas':['contabilidad','finanzas'].includes(d.id)?'6 personas entre ambas áreas':'Equipo por documentar'}</p><div className="department-card-bottom"><span>{ps.length} oportunidades</span><Badge tone={visitedDepts.has(d.id)?'green':ss.length?'blue':'neutral'}>{visitedDepts.has(d.id)?'Entrevistado':ss.length?'En agenda':'Por entrevistar'}</Badge></div></button>; })}</div><div className="note-box"><InfoCircle /><p>Los procesos que atraviesan varias áreas se registran una sola vez, con un responsable y sus dependencias, para evitar duplicar el beneficio.</p></div></>}</div>}

      {view === 'sessions' && <div className="view-enter sessions-view">
        <SectionHead title="Sesiones de trabajo" description="Un momento para escuchar. Un lugar para organizarlo todo." action={<div className="button-row"><Button variant="secondary" onClick={() => navigate('jobs')}><FileText size={15}/>Preparar con PDFs</Button>{canWrite && <Button onClick={() => newSession()}><Plus size={16} />Nueva sesión</Button>}</div>} />
        <SessionCalendar sessions={allSessions} canWrite={canWrite} onOpen={record => setModal({kind:'session',record})} onCreate={selectedDate => newSession(undefined, selectedDate)} />
        <div className="session-summary"><span><Calendar size={15} /><strong>{allSessions.filter(s=>s.status==='planned').length}</strong> programadas</span><span><CheckCircle2 size={15} /><strong>{allSessions.filter(s=>s.status==='completed').length}</strong> completadas</span><span><Paperclip size={15} /><strong>{state.evidence.filter((e:any)=>e.sessionId).length}</strong> evidencias</span></div>
      </div>}

      {view === 'opportunities' && <div className="view-enter"><SectionHead eyebrow="03 / EVALUAR" title="Oportunidades" description="Una prioridad explicable para cada proceso. La puntuación orienta la decisión y conserva el nivel de evidencia." action={canWrite&&<Button onClick={()=>newProcess()}><Plus size={17}/>Nueva oportunidad</Button>} /><div className="filter-bar"><div className="filter-search"><Search size={17}/><input aria-label="Buscar en oportunidades" placeholder="Buscar por proceso, responsable…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button className="icon-btn" onClick={()=>setQuery('')} aria-label="Borrar búsqueda"><X size={14}/></button>}</div><select aria-label="Filtrar por departamento" value={department} onChange={e=>setDepartment(e.target.value)}><option value="all">Todos los departamentos</option>{DEPARTMENTS.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select><select aria-label="Filtrar por estado" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos los estados</option>{PROCESS_STATUSES.map(s=><option key={s} value={s}>{STATUS_LABELS[s]}</option>)}</select><button className="icon-btn" title="Exportar oportunidades CSV" aria-label="Exportar oportunidades CSV" onClick={()=>run(()=>downloadCSV(state),'CSV descargado.','csv')}><Download size={18}/></button></div><section className="panel table-panel">{renderProcessTable(processes)}</section><div className="priority-explainer"><div><span className="mini-circle blue"><Target size={16}/></span><strong>Impacto × viabilidad × evidencia</strong><p>La prioridad integra ocho objetivos, complejidad, riesgo y preparación de los datos.</p></div><button className="text-button" onClick={()=>navigate('settings')}>Ver criterios <ArrowUpRight size={15}/></button></div></div>}
      {view === 'roadmap' && <Delivery {...operationsProps}/>}
      {view === 'jobs' && <JobWorkspace state={state} company={company} canWrite={canWrite} actions={app} notify={notify} openProcess={operationsProps.openProcess} prepareSession={document => setModal({ kind: 'session', record: { id: makeId(), company: document.jobDescription.company, departmentId: document.departmentId, title: `Revisión de tareas · ${document.jobDescription.role}`, date: localDate(), owner: 'Miguel Ángel', participants: [...document.jobDescription.members], notes: '', status: 'planned', processIds: [], createdAt: now(), updatedAt: now() } })}/>}
      {view === 'map' && <ProcessMap {...operationsProps}/>}
      {view === 'automations' && <AutomationCenter {...operationsProps} cloud={isCloud} workspaceId={app.user?.workspaceId} cloudUrl={app.connection?.url}/>}
      {view === 'library' && <StoreLibrary {...operationsProps}/>}

      {view === 'results' && <div className="view-enter"><SectionHead eyebrow="05 / DEMOSTRAR" title="Resultados y ROI" description="Compara cada mes el trabajo observado con la línea base al mismo volumen de actividad." action={canWrite&&<Button onClick={()=>newMeasurement()}><Plus size={17}/>Registrar medición</Button>} /><BenefitAnalysis {...operationsProps} importMeasurements={app.importMeasurements}/><div className="results-switch-label"><span className="legend-dot blue"/>PREVISIÓN DE LA CARTERA</div><div className="metrics-grid three"><Metric label="Tiempo neto previsto" value={stats.processCount?number(stats.netHoursFreedMonthly):'—'} unit={stats.processCount?'h/mes':''} detail="Capacidad que podría liberarse" icon={Clock3}/><Metric label="ROI de caja a 12 meses" value={stats.annualCashRoiPct===null?'—':`${number(stats.annualCashRoiPct)} %`} detail="Incluye inversión y operación" icon={BarChart3}/><Metric label="Recuperación de inversión" value={stats.cashPaybackMonths===null?'—':number(stats.cashPaybackMonths)} unit={stats.cashPaybackMonths===null?'':'meses'} detail="Solo si el beneficio de caja neto es positivo" icon={Activity}/></div><section className="panel observed-panel"><div className="panel-title"><div><p className="eyebrow">RESULTADOS COMPROBADOS</p><h2>{latestMonth?`Último periodo · ${monthName(latestMonth)}`:'La evidencia llegará con las mediciones'}</h2></div><Badge tone={verified.length?'green':'neutral'}>{verified.length} mediciones validadas</Badge></div>{latestVerified.length?<><div className="observed-metrics"><div><span>Tiempo liberado</span><strong>{number(latestVerified.reduce((s,x)=>s+(x.comparison.hoursFreed||0),0))}<small> h</small></strong></div><div><span>Ahorro de caja neto</span><strong>{money(latestVerified.reduce((s,x)=>s+x.comparison.netCashSaved,0))}</strong></div><div><span>Procesos comparados</span><strong>{new Set(latestVerified.map(x=>x.p.id)).size}</strong></div></div><ResultsChart entries={verified}/>{actualStats&&<div className="actual-roi-panel"><div><p className="eyebrow">ROI DEMOSTRADO · PERIODOS REGISTRADOS</p><h3>{actualStats.cashRoiPct===null?'Pendiente de evidencia económica':`${number(actualStats.cashRoiPct)} %`}</h3><p>{actualStats.unresolvedOverlap?'Revisa el reparto de beneficios compartidos antes de presentar el ROI agregado.':actualStats.needsCostValidation?'Completa la inversión real, su fuente y su validación en cada ficha para calcular el ROI comprobado.':actualStats.coverageNote}</p></div><div className="actual-roi-facts"><span>Inversión real validada <strong>{money(actualStats.actualInvestmentCost)}</strong></span><span>Caja neta tras inversión <strong>{money(actualStats.cashNetAfterInvestment)}</strong></span><span>Meses con datos <strong>{actualStats.observedMonths.length}</strong></span></div></div>}</>:<div className="observed-empty"><div className="empty-chart" aria-hidden="true"><span/><span/><span/><span/><span/><span/></div><div><h3>Preparado para el antes y el después.</h3><p>Una línea base validada, una medición con fuente y una revisión son necesarias para mostrar una mejora como comprobada.</p></div></div>}</section><section className="panel"><div className="panel-title"><h2>Registro mensual</h2><span className="muted">{allMeasurements.length} registros</span></div>{allMeasurements.length?<div className="table-scroll"><table><thead><tr><th>Periodo / proceso</th><th>Casos</th><th>Horas liberadas</th><th>Caja neta</th><th>Evidencia</th><th/></tr></thead><tbody>{[...allMeasurements].sort((a,b)=>b.month.localeCompare(a.month)).map(m=>{const p=state.processes.find(p=>p.id===m.processId)!;const c=compareMeasurement(p,m);return <tr key={m.id} className="clickable" onClick={()=>setModal({kind:'measurement',record:m})}><td><strong>{monthName(m.month)}</strong><span className="table-subtitle">{p?.name}</span></td><td className="tabular">{number(m.volume,0)}</td><td className="tabular">{number(c.hoursFreed)} h</td><td className="tabular">{money(c.netCashSaved)}</td><td><Badge tone={c.kind==='verified'?'green':'amber'}>{c.kind==='verified'?'Comprobado':c.kind==='missing-baseline'?'Sin línea base':'Por validar'}</Badge></td><td><ArrowUpRight size={15}/></td></tr>;})}</tbody></table></div>:<Empty icon={BarChart3} title="Todavía no hay mediciones" text="Registra el primer mes cuando dispongas de observaciones del proceso. Las previsiones permanecen separadas de estos resultados."/>}</section><div className="definition-grid"><article><span>01</span><h3>Tiempo liberado</h3><p>Compara la dedicación real con la línea base al volumen del mes, incluyendo revisión y retrabajo.</p></article><article><span>02</span><h3>Ahorro de caja</h3><p>Registra reducciones económicas atribuibles. El valor de las horas disponibles se presenta por separado.</p></article><article><span>03</span><h3>ROI previsto</h3><p>Beneficio de caja de 12 meses menos inversión y operación, dividido entre esos costes totales.</p></article></div></div>}

      {view === 'reports' && <div className="view-enter"><SectionHead eyebrow="06 / COMPARTIR LA VISIÓN" title="Informes" description="Informes y presentaciones construidos con los registros de tu espacio de trabajo."/><div className="report-scope"><div><strong>Ámbito del informe</strong><p>Los documentos incluyen ambas empresas y el departamento seleccionado.</p></div><select aria-label="Departamento del informe" value={reportDepartment} onChange={e=>setReportDepartment(e.target.value)}><option value="all">Informe global · Todas las áreas</option>{DEPARTMENTS.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></div><div className="report-grid"><article className="report-card"><div className="report-preview report-preview-document"><div className="paper-preview"><div className="paper-wordmark">ATLAS</div><span>PROGRAMA DE AUTOMATIZACIÓN</span><strong>Diagnóstico<br/>y evolución<br/>operativa.</strong><div className="paper-line blue"/><div className="paper-line"/><div className="paper-line short"/><div className="paper-bottom">JTQ + TE QUIERO METALES</div></div><span className="format-badge">PDF</span></div><div className="report-card-body"><h2>Informe de diagnóstico</h2><p>Estado inicial, oportunidades, prioridades, previsiones y resultados observados con su evidencia.</p><Button variant="secondary" disabled={busy==='pdf'} onClick={()=>run(()=>downloadReport(state,reportDepartment==='all'?undefined:reportDepartment),'Informe PDF generado.','pdf')}>{busy==='pdf'?<Loader2 className="spin" size={16}/>:<Download size={16}/>}Descargar informe</Button></div></article><article className="report-card"><div className="report-preview report-preview-slides"><div className="slide-preview"><span>ATLAS / COMITÉ DE DIRECCIÓN</span><strong>Una visión clara.<br/>Decisiones<br/><em>con evidencia.</em></strong><div className="slide-orb"/><small>PROGRAMA DE AUTOMATIZACIÓN</small></div><span className="format-badge">PPTX</span></div><div className="report-card-body"><h2>Presentación para Dirección</h2><p>Resumen de la cartera, cobertura, iniciativas prioritarias, recursos y evolución del programa.</p><Button variant="secondary" disabled={busy==='pptx'} onClick={()=>run(()=>downloadPresentation(state,reportDepartment==='all'?undefined:reportDepartment),'Presentación PowerPoint generada.','pptx')}>{busy==='pptx'?<Loader2 className="spin" size={16}/>:<Download size={16}/>}Descargar presentación</Button></div></article></div><section className="preparation-documents"><div><p className="eyebrow">PREPARAR EL DIAGNÓSTICO</p><h2>El método, listo para la primera sesión.</h2><p>Plan operativo y plantillas para la recogida de información, con una presentación inicial para el comité.</p></div><div className="preparation-links"><a href="/documents/ATLAS_Plan_operativo_y_plantillas.pdf" download><FileText size={19}/><span><strong>Plan y plantillas</strong><small>PDF · Método de trabajo</small></span><Download size={16}/></a><a href="/documents/ATLAS_Presentacion_ejecutiva.pptx" download><Layers3 size={19}/><span><strong>Presentación inicial</strong><small>PPTX · Comité de Dirección</small></span><Download size={16}/></a></div></section><div className="report-secondary"><FileText size={23}/><div><strong>Datos de la cartera</strong><p>Exporta las oportunidades y sus indicadores en CSV para analizarlos en una hoja de cálculo.</p></div><Button variant="ghost" onClick={()=>run(()=>downloadCSV(state),'CSV descargado.','csv')}><Download size={16}/>Exportar CSV</Button></div><div className="note-box"><ShieldCheck size={18}/><p>Los documentos identifican las estimaciones y los resultados pendientes de validación. La fecha de generación y el estado registrado acompañan cada informe.</p></div></div>}

      {view === 'settings' && <SettingsView app={app} canWrite={canWrite} run={run} notify={notify} importInput={importInput} busy={busy}/>}
    </main><footer className="app-footer"><span>ATLAS <i/> Una iniciativa de JTQ + Te Quiero Metales</span><span>Diseñado para mejorar. Medido para demostrar.</span></footer></div>
    {modal?.kind==='process'&&<ProcessEditor key={modal.record.id} process={modal.record} initialTab={modal.tab} state={state} app={app} canWrite={canWrite} onClose={()=>setModal(null)} notify={notify} onSave={async p=>{await app.saveProcess(p);setModal(null);notify('Oportunidad guardada.');}} onDelete={async p=>{await app.deleteProcess(p.id);setModal(null);notify('Oportunidad eliminada.');}}/>}
    {modal?.kind==='session'&&<SessionEditor key={modal.record.id} session={modal.record} state={state} app={app} canWrite={canWrite} onClose={()=>setModal(null)} notify={notify} onSave={async s=>{await app.saveSession(s);setModal(null);notify('Sesión guardada.');}} onDelete={async s=>{await app.deleteSession(s.id);setModal(null);notify('Sesión eliminada.');}}/>}
    {modal?.kind==='measurement'&&<MeasurementEditor key={modal.record.id} measurement={modal.record} state={state} canWrite={canWrite} onClose={()=>setModal(null)} notify={notify} onSave={async m=>{await app.saveMeasurement(m);setModal(null);notify('Medición guardada.');}} onDelete={async m=>{await app.deleteMeasurement(m.id);setModal(null);notify('Medición eliminada.');}}/>}
    {toast&&<div className={`toast ${toast.error?'toast-error':''}`} role={toast.error?'alert':'status'}>{toast.error?<HelpCircle size={19}/>:<CheckCircle2 size={19}/>}<span>{toast.text}</span><button onClick={()=>setToast(null)} aria-label="Cerrar aviso"><X size={15}/></button></div>}
  </div>;
}
function InfoCircle(){return <HelpCircle size={18}/>;}

function ProcessEditor({process,initialTab,state,app,canWrite,onClose,onSave,onDelete,notify}:{process:Process;initialTab?:string;state:AtlasState;app:any;canWrite:boolean;onClose:()=>void;onSave:(p:Process)=>Promise<void>;onDelete:(p:Process)=>Promise<void>;notify:(s:string,e?:boolean)=>void}){
  const [p,setP]=useState<Process & {aiProposal?:string}>({...process,impact:{...process.impact}});
  const [tab,setTab]=useState(initialTab||'process');
  const [saving,setSaving]=useState(false);
  const [aiLoading,setAiLoading]=useState(false);
  const [aiReviewed,setAiReviewed]=useState(false);
  const [baselineSource,setBaselineSource]=useState(process.baseline?.source||'');
  const [baselineValidated,setBaselineValidated]=useState(process.baseline?.validated||false);
  const existing=state.processes.some(x=>x.id===p.id);
  const metric=calculateMetrics(p),priority=priorityDetails(p,state.settings),rec=recommendation(p);
  const update=(key:keyof Process,value:any)=>setP(v=>({...v,[key]:value}));
  const close=()=>{if(canWrite&&JSON.stringify(p)!==JSON.stringify(process)&&!window.confirm('Hay cambios sin guardar. ¿Quieres cerrar la ficha?'))return;onClose();};
  const save=async()=>{if(!p.name.trim()) {setTab('process');notify('Escribe un nombre para la oportunidad.',true);return;} if(p.status==='pilot'&&!p.baseline){setTab('measurement');notify('Fija la línea base antes de iniciar el piloto.',true);return;}setSaving(true);try{await onSave({...p,systems:p.systems.map(x=>x.trim()).filter(Boolean),updatedAt:now()});}catch(e:any){notify(e.message||'No se pudo guardar.',true);}finally{setSaving(false);}};
  const nf=(key:keyof Process,label:string,hint?:string,suffix?:string,max?:number)=><NumberField key={key} label={label} value={Number(p[key]||0)} onChange={n=>update(key,n)} hint={hint} suffix={suffix} max={max} disabled={!canWrite}/>;
  const queryAI=async()=>{if(!p.name.trim()){setTab('process');notify('Escribe el nombre del proceso antes de analizarlo.',true);return;}if(!aiReviewed){notify('Revisa y confirma la anonimización de la ficha antes de enviarla.',true);return;}setAiLoading(true);try{await app.saveProcess({...p,updatedAt:now()});const result=await analyzeProcess(p);setP(v=>({...v,aiProposal:typeof result==='string'?result:JSON.stringify(result,null,2)}));notify('Ficha guardada y propuesta generada. Guarda de nuevo para conservar la propuesta.');}catch(e:any){notify(e.message||'La conexión de IA no está disponible.',true);}finally{setAiLoading(false);}};
  return <Modal title={existing?p.name:'Nueva oportunidad'} subtitle={existing?`${deptName(p.departmentId)} · ${COMPANY_NAMES[p.company]}`:'Describe una tarea concreta y descubre su potencial.'} onClose={close} wide><div className="modal-tabs" role="tablist">{[{id:'process',label:'Proceso'},{id:'measurement',label:'Medición'},{id:'priority',label:'Prioridad'},{id:'evidence',label:'Evidencias'},{id:'proposal',label:'Propuesta'}].map(t=><button key={t.id} role="tab" aria-selected={tab===t.id} className={tab===t.id?'active':''} onClick={()=>setTab(t.id)}>{t.label}{t.id==='evidence'&&state.evidence.filter(e=>e.processId===p.id).length>0&&<span>{state.evidence.filter(e=>e.processId===p.id).length}</span>}</button>)}</div><div className="modal-content">
  {tab==='process'&&<div className="form-grid"><Field label="Nombre de la oportunidad" className="span-2"><input autoFocus placeholder="Ej. Preparación del informe semanal de ventas" value={p.name} onChange={e=>update('name',e.target.value)} disabled={!canWrite}/></Field><Field label="Empresa"><select value={p.company} onChange={e=>update('company',e.target.value)} disabled={!canWrite}>{Object.entries(COMPANY_NAMES).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="Departamento responsable"><select value={p.departmentId} onChange={e=>update('departmentId',e.target.value)} disabled={!canWrite}>{DEPARTMENTS.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></Field><Field label="Responsable del proceso" hint="Puedes usar el puesto o un identificador interno."><input placeholder="Ej. Responsable de Contabilidad" value={p.owner} onChange={e=>update('owner',e.target.value)} disabled={!canWrite}/></Field><Field label="Estado"><select value={p.status} onChange={e=>update('status',e.target.value)} disabled={!canWrite}>{PROCESS_STATUSES.map(s=><option key={s} value={s}>{STATUS_LABELS[s]}</option>)}</select></Field><Field label="Qué se hace y qué dificultad queremos resolver" className="span-2"><textarea rows={3} placeholder="Describe el objetivo, los puntos de fricción y sus consecuencias." value={p.description} onChange={e=>update('description',e.target.value)} disabled={!canWrite}/></Field><Field label="Entrada del proceso"><textarea rows={2} placeholder="Qué lo inicia y qué información se recibe" value={p.input} onChange={e=>update('input',e.target.value)} disabled={!canWrite}/></Field><Field label="Salida esperada"><textarea rows={2} placeholder="Qué se entrega, a quién y con qué criterio" value={p.output} onChange={e=>update('output',e.target.value)} disabled={!canWrite}/></Field><Field label="Pasos actuales y excepciones" hint="Incluye transferencias entre áreas, esperas y casos que se resuelven de otra manera." className="span-2"><textarea rows={5} placeholder="1. Se recibe…&#10;2. Se comprueba…&#10;Excepciones y tareas de revisión…" value={p.currentSteps} onChange={e=>update('currentSteps',e.target.value)} disabled={!canWrite}/></Field><Field label="Herramientas y sistemas" hint="Separa cada herramienta con una coma." className="span-2"><input placeholder="ERP a medida, Google Workspace, Sage 200…" value={p.systems.join(', ')} onChange={e=>update('systems',e.target.value.split(',').map(s=>s.trim()))} disabled={!canWrite}/></Field><Field label="Notas y asuntos por confirmar" className="span-2"><textarea rows={3} placeholder="Dependencias, datos pendientes, criterios de aceptación…" value={p.notes} onChange={e=>update('notes',e.target.value)} disabled={!canWrite}/></Field></div>}
  {tab==='measurement'&&<><div className="form-section-title"><span>01</span><div><h3>El trabajo actual</h3><p>Empieza con estimaciones y conserva su origen. El tiempo por caso excluye el retrabajo.</p></div></div><div className="form-grid">{nf('volumePerMonth','Volumen mensual','Casos o transacciones del conjunto del proceso.','casos')}{nf('minutesPerCase','Dedicación por caso','Trabajo efectivo, sin tiempo de espera.','min')}{nf('peoplePerCase','Personas simultáneas por caso','No es el tamaño del departamento.','personas')}{nf('hourlyCost','Coste por hora','Valoración de capacidad; no implica ahorro de caja.','€/h')}{nf('errorRate','Casos con error','Porcentaje del volumen mensual.','%',100)}{nf('minutesPerError','Retrabajo por error','Dedicación total para corregir un caso.','min')}<Field label="Nivel de evidencia" className="span-2"><select value={p.evidenceLevel} onChange={e=>update('evidenceLevel',e.target.value)} disabled={!canWrite}><option value="estimate">Estimación del equipo</option><option value="observed">Observado en una muestra</option><option value="validated">Validado con evidencia</option></select></Field></div><div className="form-section-title"><span>02</span><div><h3>La mejora que estimamos</h3><p>Introduce hipótesis explícitas para la automatización y su supervisión.</p></div></div><div className="form-grid">{nf('automatablePct','Parte de la tarea automatizable',undefined,'%',100)}{nf('adoptionPct','Adopción prevista','Porcentaje de casos que utilizarán el nuevo flujo.','%',100)}{nf('exceptionPct','Excepciones previstas','Casos adoptados que conservan el trabajo actual.','%',100)}{nf('reviewMinutesPerCase','Supervisión por caso adoptado','Incluye los casos con excepción.','min')}{nf('errorReductionPct','Reducción prevista de errores',undefined,'%',100)}{nf('implementationCost','Coste de implantación','Incluye desarrollo, pruebas, formación y dedicación interna.','€')}{nf('monthlyRunningCost','Coste recurrente mensual','Licencias, soporte, operación e incidencias.','€/mes')}{nf('cashSavingsMonthly','Otros ahorros directos de caja','Importes que no estén incluidos en el valor de las horas.','€/mes')}{nf('cashRealizationPct','Capacidad convertida en ahorro de caja','Por defecto, 0 %. Solo si existe una reducción económica atribuible.','%',100)}</div><div className="calculation-strip"><div><span>Carga actual</span><strong>{number(metric.baselineHoursMonthly)} h/mes</strong></div><div><span>Tiempo neto previsto</span><strong>{number(metric.netHoursFreedMonthly)} h/mes</strong></div><div><span>Caja neta prevista</span><strong>{money(metric.netCashBenefitMonthly)}/mes</strong></div></div><div className="form-section-title"><span>03</span><div><h3>Inversión real de la implantación</h3><p>Se utiliza exclusivamente para el ROI demostrado de los periodos observados.</p></div></div><div className="form-grid"><NumberField label="Inversión real total" value={p.actualImplementationCost??0} onChange={n=>setP(v=>({...v,actualImplementationCost:n}))} hint="Incluye costes internos y externos efectivamente incurridos." suffix="€" disabled={!canWrite}/><Field label="Fuente del coste real"><input placeholder="Referencia de facturas, dedicaciones o cierre del proyecto" value={p.actualCostSource||''} onChange={e=>setP(v=>({...v,actualCostSource:e.target.value}))} disabled={!canWrite}/></Field><label className="check-field span-2"><input type="checkbox" checked={p.implementationCostValidated||false} onChange={e=>setP(v=>({...v,implementationCostValidated:e.target.checked,actualImplementationCost:v.actualImplementationCost??0}))} disabled={!canWrite}/><span>He comprobado la inversión real y su fuente. Si el coste es cero, la fuente lo justifica.</span></label></div><div className="baseline-box"><div className="baseline-head"><LockKeyhole size={20}/><div><h3>{p.baseline?'Línea base conservada':'Fijar la línea base'}</h3><p>{p.baseline?`Capturada el ${date(p.baseline.capturedAt)}. Este estado se usará para la comparación mensual.`:'Conserva el estado anterior a la implantación para comparar los resultados futuros.'}</p></div>{p.baseline&&<Badge tone={p.baseline.validated?'green':'amber'}>{p.baseline.validated?'Validada':'Por validar'}</Badge>}</div>{p.baseline?<div className="baseline-detail"><p><strong>Fuente:</strong> {p.baseline.source}</p><p>{number(p.baseline.volumePerMonth)} casos/mes · {number(p.baseline.minutesPerCase)} min/caso · {number(p.baseline.errorRate)} % de errores</p><span className="field-hint">La línea base guardada se conserva aunque cambien las hipótesis de mejora.</span>{canWrite&&<div className="baseline-validation"><Field label="Fuente y comprobación del estado inicial"><input value={baselineSource} onChange={e=>setBaselineSource(e.target.value)} placeholder="Referencia de la evidencia que confirma estos valores"/></Field><label className="check-field"><input type="checkbox" checked={baselineValidated} onChange={e=>setBaselineValidated(e.target.checked)}/><span>He comprobado los valores conservados con esta fuente.</span></label><Button variant="secondary" onClick={()=>{if(!baselineSource.trim()){notify('Indica una fuente para la línea base.',true);return;}setP(v=>({...v,baseline:{...v.baseline!,source:baselineSource,validated:baselineValidated}}));notify('Validación preparada. Guarda la ficha para conservarla.');}}><CheckCircle2 size={15}/>Actualizar validación</Button><p className="field-hint">Esta acción conserva los valores y la fecha de captura. Confirma su evidencia antes del piloto.</p></div>}</div>:<><Field label="Fuente de la línea base"><input placeholder="Ej. Observación de 20 casos, semana y referencia del archivo" value={baselineSource} onChange={e=>setBaselineSource(e.target.value)} disabled={!canWrite}/></Field><label className="check-field"><input type="checkbox" checked={baselineValidated} onChange={e=>setBaselineValidated(e.target.checked)} disabled={!canWrite}/><span>He comprobado estos datos con una muestra o una fuente identificable.</span></label>{canWrite&&<Button variant="secondary" onClick={()=>{if(!baselineSource.trim()){notify('Indica la fuente de la línea base.',true);return;}if(p.volumePerMonth<=0||p.minutesPerCase<=0||p.peoplePerCase<=0){notify('Completa volumen, dedicación y personas por caso antes de fijar la línea base.',true);return;}setP(v=>({...v,baseline:snapshotBaseline(v,baselineSource,baselineValidated)}));notify('Línea base preparada. Guarda la ficha para conservarla.');}}><LockKeyhole size={15}/>Fijar estado inicial</Button>}</>}</div></>}
  {tab==='priority'&&<><div className="priority-result"><Score score={priority.score}/><div><span className="eyebrow">PRIORIDAD {priority.band.toUpperCase()}</span><h3>{number(priority.score)} de 100</h3><p>Impacto ponderado por viabilidad, riesgo, datos y evidencia.</p></div><EvidenceBadge level={p.evidenceLevel}/></div><h3 className="form-heading">Impacto esperado · escala de 0 a 5</h3><p className="form-intro">0 indica que el impacto no está estimado o es nulo. 5 representa un impacto muy alto. Los pesos siguen el orden de prioridades del programa.</p><div className="impact-grid">{IMPACT_DIMENSIONS.map(d=><div className="impact-row" key={d.id}><div><strong>{d.label}</strong><span>Peso {state.settings.weights[d.id]} %</span></div><div className="rating-buttons" role="group" aria-label={`Impacto en ${d.label}`}>{[0,1,2,3,4,5].map(n=><button key={n} type="button" aria-pressed={p.impact[d.id]===n} disabled={!canWrite} className={p.impact[d.id]===n?'active':''} onClick={()=>setP(v=>({...v,impact:{...v.impact,[d.id]:n}}))}>{n}</button>)}</div></div>)}</div><div className="form-grid three"><Field label="Complejidad"><select value={p.complexity} onChange={e=>update('complexity',Number(e.target.value))} disabled={!canWrite}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} · {['Muy baja','Baja','Media','Alta','Muy alta'][n-1]}</option>)}</select></Field><Field label="Riesgo"><select value={p.risk} onChange={e=>update('risk',Number(e.target.value))} disabled={!canWrite}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} · {['Muy bajo','Bajo','Medio','Alto','Muy alto'][n-1]}</option>)}</select></Field><Field label="Preparación de datos"><select value={p.dataReadiness} onChange={e=>update('dataReadiness',Number(e.target.value))} disabled={!canWrite}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} · {['Por documentar','Incompleta','Utilizable','Estructurada','Verificada'][n-1]}</option>)}</select></Field></div><div className="score-breakdown"><div><span>Impacto</span><strong>{number(priority.impactScore)}/100</strong></div><div><span>Viabilidad</span><strong>× {number(priority.feasibilityFactor,2)}</strong></div><div><span>Riesgo</span><strong>× {number(priority.riskFactor,2)}</strong></div><div><span>Datos</span><strong>× {number(priority.dataFactor,2)}</strong></div><div><span>Evidencia</span><strong>× {number(priority.evidenceFactor,2)}</strong></div></div>{priority.warnings.map(w=><div className="inline-note" key={w}><HelpCircle size={15}/><span>{w}</span></div>)}</>}
  {tab==='evidence'&&<EvidencePanel state={state} app={app} context={{processId:p.id,departmentId:p.departmentId}} saved={existing} canWrite={canWrite} notify={notify}/>}
  {tab==='proposal'&&<><div className="proposal-heading"><span className="proposal-icon"><Sparkles size={24}/></span><div><Badge>{rec.source}</Badge><h3>{rec.title}</h3></div></div><p className="proposal-approach">{rec.approach}</p><div className="tool-chips">{rec.tools.map(t=><span key={t}>{t}</span>)}</div><div className="form-section-title"><span>01</span><div><h3>Cómo llevarlo a la práctica</h3></div></div><ol className="proposal-steps">{rec.steps.map((s,i)=><li key={s}><span>{i+1}</span><p>{s}</p></li>)}</ol><div className="proposal-columns"><div><h4>Antes de empezar</h4>{rec.prerequisites.map(s=><p key={s}><Check size={14}/>{s}</p>)}</div><div><h4>Durante la implantación</h4>{rec.safeguards.map(s=><p key={s}><ShieldCheck size={14}/>{s}</p>)}</div></div><p className="proposal-disclaimer">{rec.rationale}</p><div className="ai-box"><div><span className="eyebrow">DESARROLLO DE LA PROPUESTA</span><h3>Trabaja el caso con ChatGPT o Claude</h3><p>Copia un briefing estructurado con los datos de esta ficha. La generación conectada requiere configurar el servicio de IA.</p></div>{canWrite&&<label className="check-field ai-review-check"><input type="checkbox" checked={aiReviewed} onChange={e=>setAiReviewed(e.target.checked)}/><span>He revisado la ficha y confirmo que puede enviarse anonimizada al proveedor de IA autorizado.</span></label>}<div className="button-row"><Button variant="secondary" onClick={async()=>{try{await navigator.clipboard.writeText(buildAIPrompt(p));notify('Briefing copiado. Pégalo en ChatGPT o Claude.');}catch{notify('El navegador no ha permitido copiar al portapapeles.',true);}}}><ClipboardList size={16}/>Copiar briefing</Button>{canWrite&&<Button onClick={queryAI} disabled={aiLoading||!aiReviewed}>{aiLoading?<Loader2 className="spin" size={16}/>:<Sparkles size={16}/>}Generar con IA conectada</Button>}</div><Field label="Propuesta desarrollada" hint="Puedes pegar aquí la respuesta revisada de tu asistente."><textarea rows={8} placeholder="Añade la propuesta, los pasos técnicos, las dependencias y los costes por confirmar." value={p.aiProposal||''} onChange={e=>setP(v=>({...v,aiProposal:e.target.value}))} disabled={!canWrite}/></Field></div></>}
  </div><footer className="modal-footer"><div>{existing&&canWrite&&<button className="danger-link" onClick={async()=>{if(!window.confirm('¿Eliminar esta oportunidad? Si tiene registros vinculados, consérvala como descartada.'))return;try{await onDelete(p);}catch(e:any){notify(e.message,true);}}}><Trash2 size={15}/>Eliminar</button>}</div><div className="button-row"><Button variant="ghost" onClick={close}>{canWrite?'Cancelar':'Cerrar'}</Button>{canWrite&&<Button onClick={save} disabled={saving}>{saving?<Loader2 className="spin" size={16}/>:<Check size={16}/>}Guardar oportunidad</Button>}</div></footer></Modal>;
}

function SessionEditor({session,state,app,canWrite,onClose,onSave,onDelete,notify}:{session:Session;state:AtlasState;app:any;canWrite:boolean;onClose:()=>void;onSave:(s:Session)=>Promise<void>;onDelete:(s:Session)=>Promise<void>;notify:(s:string,e?:boolean)=>void}){
  const [s,setS]=useState({...session});const [tab,setTab]=useState('notes');const [saving,setSaving]=useState(false);const exists=state.sessions.some(x=>x.id===s.id);const change=(k:keyof Session,v:any)=>setS(old=>({...old,[k]:v}));const close=()=>{if(canWrite&&JSON.stringify(s)!==JSON.stringify(session)&&!window.confirm('Hay notas o cambios sin guardar. ¿Quieres cerrar?'))return;onClose();};
  const save=async()=>{if(!s.title.trim()||!s.date){notify('Añade un título y una fecha para la sesión.',true);return;}setSaving(true);try{await onSave({...s,participants:s.participants.map(x=>x.trim()).filter(Boolean),updatedAt:now()});}catch(e:any){notify(e.message,true);}finally{setSaving(false);}};
  return <Modal title={exists?s.title:'Nueva sesión de trabajo'} subtitle="Una conversación bien documentada es el inicio del diagnóstico." onClose={close} wide><div className="modal-tabs"><button className={tab==='notes'?'active':''} onClick={()=>setTab('notes')}>Sesión y notas</button><button className={tab==='tasks'?'active':''} onClick={()=>setTab('tasks')}>Tareas precargadas</button><button className={tab==='guide'?'active':''} onClick={()=>setTab('guide')}>Guion de entrevista</button><button className={tab==='evidence'?'active':''} onClick={()=>setTab('evidence')}>Archivos y evidencias</button></div><div className="modal-content">{tab==='notes'&&<div className="form-grid"><Field label="Título de la sesión" className="span-2"><input placeholder="Ej. Diagnóstico inicial de Contabilidad" value={s.title} onChange={e=>change('title',e.target.value)} disabled={!canWrite}/></Field><Field label="Departamento"><select value={s.departmentId} onChange={e=>change('departmentId',e.target.value)} disabled={!canWrite}>{DEPARTMENTS.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></Field><Field label="Empresa"><select value={s.company} onChange={e=>change('company',e.target.value)} disabled={!canWrite}>{Object.entries(COMPANY_NAMES).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="Fecha"><input type="date" value={s.date} onChange={e=>change('date',e.target.value)} disabled={!canWrite}/></Field><Field label="Estado"><select value={s.status} onChange={e=>change('status',e.target.value)} disabled={!canWrite}><option value="planned">Programada</option><option value="completed">Completada</option></select></Field><Field label="Coordinación"><input value={s.owner} onChange={e=>change('owner',e.target.value)} disabled={!canWrite}/></Field><Field label="Participantes" hint="Usa puestos o identificadores, separados por comas."><input placeholder="Responsable, persona ejecutora…" value={s.participants.join(', ')} onChange={e=>change('participants',e.target.value.split(',').map(v=>v.trim()))} disabled={!canWrite}/></Field><Field label="Notas de la sesión" className="span-2" hint="Incluye hechos, estimaciones, preguntas pendientes y acuerdos. Se guardan al pulsar Guardar sesión."><textarea className="session-notes" rows={13} placeholder="OBJETIVO Y CONTEXTO&#10;&#10;PROCESOS Y TAREAS OBSERVADOS&#10;&#10;VOLUMEN, TIEMPOS Y EXCEPCIONES&#10;&#10;OPORTUNIDADES DETECTADAS&#10;&#10;EVIDENCIAS Y DATOS POR CONFIRMAR&#10;&#10;ACUERDOS Y SIGUIENTES PASOS" value={s.notes} onChange={e=>change('notes',e.target.value)} disabled={!canWrite}/></Field>{state.processes.filter(p=>p.departmentId===s.departmentId).length>0&&<div className="field span-2"><span className="field-label">Oportunidades relacionadas</span><div className="linked-checks">{state.processes.filter(p=>p.departmentId===s.departmentId).map(p=><label className="check-field" key={p.id}><input type="checkbox" checked={s.processIds.includes(p.id)} onChange={e=>change('processIds',e.target.checked?[...s.processIds,p.id]:s.processIds.filter(id=>id!==p.id))} disabled={!canWrite}/><span>{p.name}</span></label>)}</div></div>}</div>}{tab==='tasks'&&<SessionPreparation session={s} state={state} actions={app} canWrite={canWrite} notify={notify}/>} {tab==='guide'&&<div className="session-guide"><p className="eyebrow">{deptName(s.departmentId)}</p><h3>Una tarea real, paso a paso.</h3><p>Pide que te enseñen un caso habitual y una excepción. Anota el trabajo efectivo y la espera por separado.</p><ol>{PROMPTS[s.departmentId].map((q,i)=><li key={q}><span>{String(i+1).padStart(2,'0')}</span>{q}</li>)}</ol><h4>Para cada proceso, confirma</h4><div className="guide-checklist">{['Qué lo inicia y qué resultado debe entregar.','Quién lo realiza y qué sistemas utiliza.','Cuántas veces ocurre y cuánto trabajo consume.','Qué errores, esperas y excepciones aparecen.','Qué evidencia permite comprobar la estimación.','Quién valida el diagnóstico y los siguientes pasos.'].map(q=><div key={q}><CheckCircle2 size={16}/>{q}</div>)}</div></div>}{tab==='evidence'&&<EvidencePanel state={state} app={app} context={{sessionId:s.id,departmentId:s.departmentId}} saved={exists} canWrite={canWrite} notify={notify}/>}</div><footer className="modal-footer"><div>{exists&&canWrite&&<button className="danger-link" onClick={async()=>{if(!window.confirm('¿Eliminar esta sesión? Elimina antes sus adjuntos si ya no necesitas conservarlos.'))return;try{await onDelete(s);}catch(e:any){notify(e.message,true);}}}><Trash2 size={15}/>Eliminar</button>}</div><div className="button-row"><Button variant="ghost" onClick={close}>{canWrite?'Cancelar':'Cerrar'}</Button>{canWrite&&<Button onClick={save} disabled={saving}>{saving?<Loader2 className="spin" size={16}/>:<Check size={16}/>}Guardar sesión</Button>}</div></footer></Modal>;
}

function MeasurementEditor({measurement,state,canWrite,onClose,onSave,onDelete,notify}:{measurement:Measurement;state:AtlasState;canWrite:boolean;onClose:()=>void;onSave:(m:Measurement)=>Promise<void>;onDelete:(m:Measurement)=>Promise<void>;notify:(s:string,e?:boolean)=>void}){
  const [m,setM]=useState({...measurement});const [saving,setSaving]=useState(false);const p=state.processes.find(p=>p.id===m.processId);const c=p?compareMeasurement(p,m):null;const exists=state.measurements.some(x=>x.id===m.id);const change=(k:keyof Measurement,v:any)=>setM(old=>({...old,[k]:v}));const close=()=>{if(canWrite&&JSON.stringify(m)!==JSON.stringify(measurement)&&!window.confirm('Hay cambios sin guardar. ¿Quieres cerrar?'))return;onClose();};const nf=(k:keyof Measurement,label:string,hint?:string,suffix?:string)=><NumberField key={k} label={label} value={Number(m[k]||0)} onChange={n=>change(k,n)} hint={hint} suffix={suffix} disabled={!canWrite}/>;
  const save=async()=>{if(!m.processId||!m.month){notify('Selecciona un proceso y un periodo.',true);return;}if(m.errors>m.volume){notify('Los casos con error no pueden superar el volumen observado.',true);return;}if(m.validated&&(!m.source.trim()||m.volume<=0)){notify('Una medición validada necesita una fuente y casos observados.',true);return;}setSaving(true);try{await onSave({...m,updatedAt:now()});}catch(e:any){notify(e.message,true);}finally{setSaving(false);}};
  return <Modal title={exists?'Revisión de la medición':'Nueva medición mensual'} subtitle="Registra lo que ocurrió y la evidencia que permite comprobarlo." onClose={close} wide><div className="modal-content"><div className="form-grid"><Field label="Proceso observado"><select value={m.processId} onChange={e=>change('processId',e.target.value)} disabled={!canWrite}>{state.processes.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Periodo"><input type="month" value={m.month} onChange={e=>change('month',e.target.value)} disabled={!canWrite}/></Field></div>{!p?.baseline&&<div className="notice notice-amber"><HelpCircle size={18}/><span>Este proceso todavía no tiene una línea base. Puedes guardar la observación, pero la mejora no se considerará comprobada.</span></div>}<div className="form-section-title"><span>01</span><div><h3>Actividad observada</h3><p>Registra la dedicación total del nuevo proceso, manteniendo el retrabajo y la revisión separados.</p></div></div><div className="form-grid">{nf('volume','Casos procesados',undefined,'casos')}{nf('minutesPerCase','Dedicación por caso','Sin incluir el retrabajo ni la revisión indicada aparte.','min')}{nf('peoplePerCase','Personas simultáneas por caso',undefined,'personas')}{nf('errors','Casos con error',undefined,'casos')}{nf('minutesPerError','Retrabajo por error',undefined,'min')}{nf('reviewMinutes','Revisión total del mes','Incluye las comprobaciones y la supervisión.','min')}{nf('runningCost','Coste operativo base del mes','Excluye los extras de mantenimiento e IA que indiques a continuación.','€')}{nf('maintenanceCost','Mantenimiento adicional del mes',undefined,'€')}{nf('aiCost','IA adicional del mes',undefined,'€')}{nf('realCashSaved','Ahorro de caja bruto del mes','Solo reducciones económicas atribuibles; antes de restar la operación.','€')}<Field label="Fuente de la medición" className="span-2"><textarea rows={2} placeholder="Informe o muestra utilizada, periodo, referencia del archivo y cómo se obtuvo el dato" value={m.source} onChange={e=>change('source',e.target.value)} disabled={!canWrite}/></Field><Field label="Observaciones y cambios de contexto" className="span-2"><textarea rows={3} placeholder="Cambios de volumen, incidencias, costes extraordinarios y factores que puedan afectar a la comparación" value={m.notes} onChange={e=>change('notes',e.target.value)} disabled={!canWrite}/></Field><label className="check-field span-2"><input type="checkbox" checked={m.validated} onChange={e=>change('validated',e.target.checked)} disabled={!canWrite}/><span>He revisado la medición y puedo relacionarla con la fuente indicada.</span></label></div>{c&&<><div className="calculation-strip"><div><span>Base al volumen observado</span><strong>{number(c.baselineHoursAtObservedVolume)} h</strong></div><div><span>Dedicación observada</span><strong>{number(c.observedHours)} h</strong></div><div><span>Tiempo liberado</span><strong>{number(c.hoursFreed)} h</strong></div></div><div className="measurement-status"><Badge tone={c.kind==='verified'?'green':'amber'}>{c.kind==='verified'?'Comparación comprobada':c.kind==='missing-baseline'?'Falta línea base':'Comparación por validar'}</Badge><span>Caja neta: <strong>{money(c.netCashSaved)}</strong></span></div>{c.warnings.map(w=><div className="inline-note" key={w}><HelpCircle size={15}/>{w}</div>)}</>}</div><footer className="modal-footer"><div>{exists&&canWrite&&<button className="danger-link" onClick={async()=>{if(!window.confirm('¿Eliminar esta medición?'))return;try{await onDelete(m);}catch(e:any){notify(e.message,true);}}}><Trash2 size={15}/>Eliminar</button>}</div><div className="button-row"><Button variant="ghost" onClick={close}>{canWrite?'Cancelar':'Cerrar'}</Button>{canWrite&&<Button onClick={save} disabled={saving}>{saving?<Loader2 className="spin" size={16}/>:<Check size={16}/>}Guardar medición</Button>}</div></footer></Modal>;
}

function EvidencePanel({state,app,context,saved,canWrite,notify}:{state:AtlasState;app:any;context:{processId?:string;sessionId?:string;departmentId?:string};saved:boolean;canWrite:boolean;notify:(s:string,e?:boolean)=>void}){
  const input=useRef<HTMLInputElement>(null);const [anonymized,setAnonymized]=useState(false);const [uploading,setUploading]=useState(false);const list=state.evidence.filter((e:any)=>context.processId?e.processId===context.processId:e.sessionId===context.sessionId);
  const upload=async(files:FileList|null)=>{if(!files?.length)return;if(!anonymized){notify('Confirma que los archivos están anonimizados antes de subirlos.',true);return;}setUploading(true);try{for(const file of Array.from(files)){await app.addEvidence(file,{...context,anonymized:true});}notify('Evidencias guardadas.');}catch(e:any){notify(e.message||'No se pudo guardar el archivo.',true);}finally{setUploading(false);if(input.current)input.current.value='';}};
  return <div className="evidence-panel"><div className="form-section-title"><span><Paperclip size={18}/></span><div><h3>El contexto también se documenta</h3><p>Adjunta fotos, vídeos y documentos que expliquen el proceso o respalden sus mediciones.</p></div></div>{!saved?<div className="notice notice-amber"><HelpCircle size={18}/><span>Guarda primero la ficha. Después podrás añadir y consultar sus archivos.</span></div>:canWrite&&<><label className="check-field anonymization-check"><input type="checkbox" checked={anonymized} onChange={e=>setAnonymized(e.target.checked)}/><span>He revisado los archivos y eliminado los datos personales o identificadores que no deben compartirse.</span></label><button className={`upload-drop ${!anonymized?'disabled':''}`} disabled={!anonymized||uploading} onClick={()=>input.current?.click()} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();if(anonymized&&!uploading)upload(e.dataTransfer.files);}}>{uploading?<Loader2 className="spin" size={26}/>:<Upload size={26}/>}<strong>{uploading?'Guardando evidencias…':'Selecciona o arrastra tus archivos'}</strong><span>Fotos, vídeos, PDF y documentos · máximo 50 MB por archivo</span><div><ImageIcon size={17}/><Video size={17}/><FileText size={17}/></div></button><input ref={input} type="file" multiple accept="image/*,video/*,.pdf,.docx,.xlsx,.csv,.txt,.json" className="sr-only" onChange={e=>upload(e.target.files)}/></>}{list.length?<div className="evidence-list">{list.map((e:any)=><article key={e.id}><span className="file-icon">{e.mimeType?.startsWith('image/')?<ImageIcon size={22}/>:e.mimeType?.startsWith('video/')?<Video size={22}/>:<FileText size={22}/>}</span><div><strong>{e.fileName||e.name}</strong><span>{filesize(e.size)} · {date(e.createdAt)}</span></div><button className="icon-btn" title="Abrir evidencia" aria-label={`Abrir ${e.name}`} onClick={async()=>{try{await app.openEvidence(e);}catch(err:any){notify(err.message,true);}}}><ArrowUpRight size={17}/></button><button className="icon-btn" title="Descargar evidencia" aria-label={`Descargar ${e.name}`} onClick={async()=>{try{await app.downloadEvidence(e);}catch(err:any){notify(err.message,true);}}}><Download size={17}/></button>{canWrite&&<button className="icon-btn danger-icon" aria-label={`Eliminar ${e.name}`} onClick={async()=>{if(!window.confirm(`¿Eliminar la evidencia «${e.name}»?`))return;try{await app.deleteEvidence(e.id);notify('Evidencia eliminada.');}catch(err:any){notify(err.message,true);}}}><Trash2 size={16}/></button>}</article>)}</div>:saved&&<p className="no-files">Esta ficha todavía no tiene archivos adjuntos.</p>}</div>;
}

function ResultsChart({entries}:{entries:Array<{m:Measurement;p:Process;comparison:ReturnType<typeof compareMeasurement>}>}){
  const months=[...new Set(entries.map(x=>x.m.month))].sort().slice(-6);const values=months.map(month=>entries.filter(x=>x.m.month===month).reduce((s,x)=>s+(x.comparison.hoursFreed||0),0));const max=Math.max(...values.map(Math.abs),1);const width=640,height=190,left=45,bottom=155,top=15;const hasNegative=values.some(x=>x<0);const zero=hasNegative?90:bottom;const range=hasNegative?65:130;const barWidth=Math.min(44,440/Math.max(months.length,1));
  return <div className="results-chart"><div className="chart-heading"><span>Tiempo liberado por mes</span><span><span className="legend-dot blue"/>Mediciones validadas</span></div><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Horas liberadas mensuales en mediciones validadas"><line x1={left} y1={zero} x2={620} y2={zero} stroke="#d8dce2"/>{values.map((value,i)=>{const x=left+(i+.5)*(560/months.length);const h=Math.abs(value)/max*range;return <g key={months[i]}><rect x={x-barWidth/2} y={value>=0?zero-h:zero} width={barWidth} height={Math.max(h,1)} rx="6" fill={value>=0?'#3265f0':'#e6a466'}/><text x={x} y={value>=0?zero-h-10:zero+h+17} textAnchor="middle" fill="#515967" fontSize="12">{number(value)} h</text><text x={x} y={182} textAnchor="middle" fill="#6b7280" fontSize="11">{monthName(months[i])}</text></g>;})}</svg></div>;
}

function SettingsView({app,canWrite,run,notify,importInput,busy}:{app:any;canWrite:boolean;run:(a:()=>any,s?:string,n?:string)=>Promise<void>;notify:(s:string,e?:boolean)=>void;importInput:any;busy:string}){
  const state:AtlasState=app.state;const [settings,setSettings]=useState<Settings>({...state.settings,weights:{...state.settings.weights}});const [url,setUrl]=useState(app.connection?.url||'');const [key,setKey]=useState(app.connection?.key||'');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [showConnection,setShowConnection]=useState(false);const weightSum=Object.values(settings.weights).reduce((a,b)=>a+b,0);const cloud=app.mode==='cloud'||app.mode==='supabase';
  useEffect(()=>setSettings({...state.settings,weights:{...state.settings.weights}}),[state.settings]);
  useEffect(()=>{setUrl(app.connection?.url||'');setKey(app.connection?.key||'');},[app.connection]);
  return <div className="view-enter"><SectionHead eyebrow="CONFIGURACIÓN DEL PROGRAMA" title="Configuración" description="Criterios, acceso al espacio y conservación de la información."/><div className="settings-layout"><section className="panel settings-panel"><div className="panel-title"><div><p className="eyebrow">MODELO DE PRIORIZACIÓN</p><h2>Los objetivos marcan el orden</h2></div><Badge tone={weightSum===100?'green':'amber'}>{weightSum} / 100</Badge></div><p className="panel-copy">Los pesos expresan las prioridades de Dirección. La puntuación también tiene en cuenta la complejidad, el riesgo, los datos disponibles y la evidencia.</p><div className="weight-list">{IMPACT_DIMENSIONS.map((d,i)=><div key={d.id}><span className="weight-index">{String(i+1).padStart(2,'0')}</span><strong>{d.label}</strong><div className="weight-track"><span style={{width:`${Math.min(settings.weights[d.id]*2.6,100)}%`}}/></div><div className="weight-input"><input type="number" min="0" max="100" aria-label={`Peso de ${d.label}`} value={settings.weights[d.id]} disabled={!canWrite} onChange={e=>setSettings(s=>({...s,weights:{...s.weights,[d.id]:Math.max(0,Math.min(100,Number(e.target.value)||0))}}))}/><span>%</span></div></div>)}</div>{canWrite&&<div className="settings-footer"><button className="text-button" onClick={()=>setSettings(s=>({...s,weights:{...DEFAULT_SETTINGS.weights}}))}>Restaurar propuesta inicial</button><Button onClick={()=>{if(weightSum!==100){notify('Ajusta los pesos para que sumen 100 antes de guardar.',true);return;}run(()=>app.saveSettings(settings),'Criterios actualizados.');}}><Check size={16}/>Guardar criterios</Button></div>}</section><div className="settings-side"><section className="panel settings-panel"><div className="panel-title"><div><p className="eyebrow">DATOS DEL PROGRAMA</p><h2>Tu espacio, a salvo</h2></div><FolderOpen size={21}/></div><p className="panel-copy">La copia completa incluye los registros y los archivos adjuntos. Consérvala al terminar cada jornada de entrevistas.</p><Button variant="secondary" onClick={()=>run(()=>app.exportBackup(),'Copia completa descargada.','backup')} disabled={busy==='backup'}>{busy==='backup'?<Loader2 className="spin" size={16}/>:<Download size={16}/>}Exportar copia completa</Button>{canWrite&&<><Button variant="ghost" onClick={()=>importInput.current?.click()}><Upload size={16}/>Importar una copia</Button><input type="file" accept=".zip,.json,application/zip,application/json" ref={importInput} className="sr-only" onChange={e=>{const file=e.target.files?.[0];if(!file)return;run(()=>app.importBackup(file),'Copia importada.','import');e.target.value='';}}/></>}<div className="inline-note"><LockKeyhole size={14}/><span>{cloud?'El espacio está conectado a Supabase.':'En modo local, cada navegador conserva su propia información.'}</span></div></section><section className="panel settings-panel demo-panel"><span className="round-icon"><Play size={20}/></span><h3>Explora un caso de ejemplo</h3><p>Comprueba los formularios, las prioridades y el seguimiento con datos ficticios en un espacio separado.</p><button className="text-button" onClick={()=>run(()=>app.mode==='demo'?app.clearDemo():app.loadDemo(),app.mode==='demo'?'Has vuelto a tus datos.':'Espacio de ejemplo abierto.')}>{app.mode==='demo'?'Volver a mis datos':'Abrir demostración'}<ArrowRight size={15}/></button></section></div></div><section className="panel ai-settings-panel"><div className="panel-title"><div><p className="eyebrow">ASISTENCIA CONECTADA</p><h2>Análisis con el proveedor autorizado</h2></div><Sparkles size={21}/></div><p className="panel-copy">El análisis conectado utiliza la función de servidor y las claves configuradas en Supabase. El briefing para ChatGPT y Claude funciona también en modo local.</p><label className="check-field ai-enable-check"><input type="checkbox" checked={settings.aiEnabled} disabled={!canWrite} onChange={e=>{const value=e.target.checked;run(async()=>{await app.saveSettings({aiEnabled:value});setSettings(old=>({...old,aiEnabled:value}));},value?'Análisis conectado habilitado.':'Análisis conectado deshabilitado.');}}/><span>Permitir el análisis de fichas anonimizadas con la IA conectada.</span></label></section><section className="panel connection-panel"><div className="panel-title"><div><p className="eyebrow">ACCESO Y SINCRONIZACIÓN</p><h2>{app.user?'Sesión conectada':cloud?'Accede al espacio compartido':'Preparado para trabajar en equipo'}</h2></div><Badge tone={cloud?'green':'neutral'}>{cloud?'Supabase conectado':'Modo local'}</Badge></div><p className="panel-copy">El espacio compartido utiliza el acceso y los permisos de Supabase. Dirección consulta la información y el responsable del programa gestiona los registros.</p>{app.user?<div className="signed-in"><span className="avatar"><Users size={20}/></span><div><strong>{app.user.email||'Usuario autenticado'}</strong><span>{app.user.role==='director'?'Dirección · Solo lectura':'Responsable · Edición del programa'}</span></div><Button variant="secondary" onClick={()=>run(()=>app.signOut(),'Sesión cerrada.')}><LogOut size={15}/>Cerrar sesión</Button></div>:<div className="login-form"><Field label="Correo corporativo"><input type="email" autoComplete="username" placeholder="tu@empresa.com" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label="Contraseña"><input type="password" autoComplete="current-password" placeholder="Tu contraseña" value={password} onChange={e=>setPassword(e.target.value)}/></Field><Button onClick={()=>run(async()=>{await app.signIn(email,password);setPassword('');},'Sesión iniciada.','login')} disabled={!email||!password||busy==='login'}>{busy==='login'?<Loader2 className="spin" size={16}/>:<LockKeyhole size={16}/>}Iniciar sesión</Button></div>}{canWrite&&<><button className="connection-toggle" onClick={()=>setShowConnection(!showConnection)}><Link2 size={15}/>Configurar conexión del proyecto<ChevronDown size={15} className={showConnection?'rotate':''}/></button>{showConnection&&<div className="connection-form"><div className="form-grid"><Field label="URL de Supabase"><input type="url" placeholder="https://tu-proyecto.supabase.co" value={url} onChange={e=>setUrl(e.target.value)}/></Field><Field label="Clave publicable" hint="Usa exclusivamente la clave publicable o anon. Nunca la service_role."><input type="password" autoComplete="off" placeholder="sb_publishable_…" value={key} onChange={e=>setKey(e.target.value)}/></Field></div><div className="button-row"><Button variant="secondary" onClick={()=>run(()=>app.configureConnection({url:url.trim(),key:key.trim()}),'Conexión guardada. Inicia sesión con un usuario autorizado.','connect')} disabled={busy==='connect'}><Link2 size={15}/>Guardar conexión</Button><span className="field-hint">La base de datos, sus permisos y los usuarios deben estar provisionados.</span></div></div>}</>}</section></div>;
}
